"""Resolve explicit Section-end copies without using coordinates or names."""


def expand_joint_selection(controls, selected, source_count):
    """Return source indices selected together for one logical Street control.

    These indices are disposable compiled lookups, not semantic identities.
    Each source vertex must appear exactly once in the current binding. Only
    recorded primary/alias pairs are related; coincident other Streets remain
    independent. The caller validates the live source lookup before mutation.
    """
    if type(source_count) is not int or source_count < 1:
        raise ValueError('The source binding needs a positive vertex count')
    peers = {}
    seen = set()
    for vertex, alias in controls:
        if type(vertex) is not int or type(alias) is not int:
            raise ValueError('Source joint references must be integer indices')
        if not 0 <= vertex < source_count or not -1 <= alias < source_count:
            raise ValueError('Source joint reference is outside the source layout')
        indices = (vertex,) if alias == -1 else (vertex, alias)
        for index in indices:
            if index in seen:
                raise ValueError('Source joint reference has multiple owners')
            seen.add(index)
        if alias >= 0:
            peers[vertex] = alias
            peers[alias] = vertex
    if len(seen) != source_count:
        raise ValueError('Source joint binding does not cover every source vertex')
    selected = tuple(selected)
    if any(type(i) is not int or i not in seen for i in selected):
        raise ValueError('Selected vertex is outside the source layout')
    result = set(selected)
    return result | {peers[i] for i in result if i in peers}
